diagrams.content:
graph LR
    TP[トップページ] --> A1(アンケート入力1);
    A1 --> A2(アンケート入力2);
    A1 --> TL(トピック一覧);
    A2 --> AC(アンケート確認);
    AC --> AS(アンケート送信完了);
    AS --> T1(トピック);
    TL --> TS(トピック検索);
    TL --> T2(トピック);
    TS --> TR(トピック検索結果);
    TR --> T3(トピック);

graph LR
    A1[アンケート入力1] -- i --> A2(アンケート入力2);
    A2 -- ii --> AC(アンケート確認);
    AC -- iii --> AS(アンケート送信完了);

graph TD
    TP[トップページ] --> L(ログイン);
    L --> A(ログイン後のトップページ);

    A --> SA(会員情報変更入力);
    SA -- (A) --> SB(会員情報変更確認);
    SB -- (B) --> SC(会員情報変更完了);

    A --> CA(キャンペーン一覧);
    CA --> CB(キャンペーン申込み);
    CB -- (C) --> CC(キャンペーン申込み完了);

    A --> DU(製品情報一覧);
    DU -- (D) --> DL(製品情報);

    A --> EA(よくある質問検索);
    EA --> EB(検索結果);
    EB -- (E) --> EC(よくある質問);

    TP --> N1(新規会員登録申込み);
    N1 --> N2(電子メールで登録URLを送付);
    N2 -- 登録URLアクセス --> N3(新規会員情報入力);
    N3 --> N4(新規会員情報確認);
    N4 --> N5(新規会員登録完了);
